module sort_minimum_swaps(\n    input clk, rst_n, start,\n    input [7:0] initial_perm,\n    input [23:0] swaps,\n    input [2:0] num_swaps,\n    output reg [4:0] min_swaps,\n    output reg done,\n    output reg error\n);\n\n// State declarations\nlocalparam [2:0] STATE_IDLE = 3'd0;\nlocalparam [2:0] STATE_INIT = 3'd1;\nlocalparam [2:0] STATE_DEQUEUE = 3'd2;\nlocalparam [2:0] STATE_CHECK = 3'd3;\nlocalparam [2:0] STATE_PROCESS_SWAP = 3'd4;\nlocalparam [2:0] STATE_NEXT_SWAP = 3'd5;\nlocalparam [2:0] STATE_DONE = 3'd6;\nlocalparam [2:0] STATE_ERROR = 3'd7;\n\n// Internal registers\nreg [2:0] current_state, next_state;\nreg [7:0] target_perm;\nreg [4:0] distance_reg;\nreg [7:0] current_perm;\nreg [2:0] swap_counter;\nreg [7:0] new_perm;\nreg [255:0] visited;\nreg [7:0] queue [0:23];\nreg [4:0] dist_queue [0:23];\nreg [4:0] head, tail;\nreg [4:0] cycle_count;\nlocalparam [4:0] MAX_CYCLES = 5'd20;\n\n// FIFO status\nwire fifo_empty = (head == tail);\n\n// Swap extraction\nwire [1:0] swap_pos1 = swaps[swap_counter*4 +: 2];\nwire [1:0] swap_pos2 = swaps[swap_counter*4 + 2 +: 2];\n\n// Function to perform swap\nfunction [7:0] perform_swap;\n    input [7:0] perm;\n    input [1:0] pos1;\n    input [1:0] pos2;\n    reg [1:0] val1, val2;\n    reg [7:0] result;\n    begin\n        val1 = perm[pos1*2 +: 2];\n        val2 = perm[pos2*2 +: 2];\n        result = perm;\n        result[pos1*2 +: 2] = val2;\n        result[pos2*2 +: 2] = val1;\n        perform_swap = result;\n    end\nendfunction\n\n// State transition\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        current_state <= STATE_IDLE;\n    end else begin\n        current_state <= next_state;\n    end\nend\n\n// Next state logic\nalways @(*) begin\n    next_state = current_state;\n    case (current_state)\n        STATE_IDLE: begin\n            if (start) next_state = STATE_INIT;\n        end\n        STATE_INIT: begin\n            next_state = STATE_DEQUEUE;\n        end\n        STATE_DEQUEUE: begin\n            if (fifo_empty) next_state = STATE_ERROR;\n            else next_state = STATE_CHECK;\n        end\n        STATE_CHECK: begin\n            if (current_perm == target_perm) next_state = STATE_DONE;\n            else next_state = STATE_PROCESS_SWAP;\n        end\n        STATE_PROCESS_SWAP: begin\n            if (swap_counter >= num_swaps) next_state = STATE_DEQUEUE;\n            else if (visited[new_perm]) next_state = STATE_NEXT_SWAP;\n            else next_state = STATE_NEXT_SWAP;\n        end\n        STATE_NEXT_SWAP: begin\n            if (swap_counter < num_swaps) next_state = STATE_PROCESS_SWAP;\n            else next_state = STATE_DEQUEUE;\n        end\n        STATE_DONE, STATE_ERROR: begin\n            next_state = STATE_IDLE;\n        end\n        default: next_state = STATE_IDLE;\n    endcase\nend\n\n// Datapath\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        min_swaps <= 5'd0;\n        done <= 1'b0;\n        error <= 1'b0;\n        distance_reg <= 5'd0;\n        swap_counter <= 3'd0;\n        head <= 5'd0;\n        tail <= 5'd0;\n        visited <= 256'd0;\n        target_perm <= 8'b00_01_10_11;\n        cycle_count <= 5'd0;\n    end else begin\n        done <= 1'b0;\n        error <= 1'b0;\n        cycle_count <= cycle_count + 5'd1;\n        \n        case (current_state)\n            STATE_INIT: begin\n                visited <= 256'd0;\n                head <= 5'd0;\n                tail <= 5'd0;\n                distance_reg <= 5'd0;\n                swap_counter <= 3'd0;\n                queue[0] <= initial_perm;\n                dist_queue[0] <= 5'd0;\n                tail <= 5'd1;\n                visited[initial_perm] <= 1'b1;\n                cycle_count <= 5'd0;\n            end\n            \n            STATE_DEQUEUE: begin\n                if (!fifo_empty) begin\n                    current_perm <= queue[head];\n                    distance_reg <= dist_queue[head];\n                    head <= head + 5'd1;\n                    swap_counter <= 3'd0;\n                end\n            end\n            \n            STATE_PROCESS_SWAP: begin\n                if (swap_counter < num_swaps) begin\n                    new_perm <= perform_swap(current_perm, swap_pos1, swap_pos2);\n                end\n            end\n            \n            STATE_NEXT_SWAP: begin\n                if (swap_counter < num_swaps && !visited[new_perm]) begin\n                    if (tail < 5'd24) begin\n                        queue[tail] <= new_perm;\n                        dist_queue[tail] <= distance_reg + 5'd1;\n                        tail <= tail + 5'd1;\n                        visited[new_perm] <= 1'b1;\n                    end\n                end\n                swap_counter <= swap_counter + 3'd1;\n            end\n            \n            STATE_DONE: begin\n                min_swaps <= distance_reg;\n                done <= 1'b1;\n            end\n            \n            STATE_ERROR: begin\n                error <= 1'b1;\n            end\n        endcase\n        \n        // Safety: return to idle if cycles exceed max\n        if (cycle_count >= MAX_CYCLES && current_state != STATE_IDLE && current_state != STATE_DONE && current_state != STATE_ERROR) begin\n            error <= 1'b1;\n        end\n    end\nend\n\nendmodule